mapper.select:
select a.*,t.allowupdate,t.allowformula,
 row_number() over (order by t.showorder,a.bblc) rn
 from
  (SELECT * FROM  tjbb_line_item t WHERE t.qybj='Y' and bbdm=#{bbdm}) t ,
  ${fname} a
  where  t.bblc(+)=a.bblc
    and a.swjgdm = #{swjgdm} and a.ssny=#{ssny}
and exists (
        select 1 from tjbb_line_item k ,tjbb_report_list r, tjbb_task f
        where k.bbdm=r.bbdm and r.bbdldm=f.bbdldm and a.swjgdm=f.swjgdm


                and  f.swjgdm=#{swjgdm}


                and  f.swjgdm=#{curSwjgdm}


                and  f.sjswjg=#{curSwjgdm}


        and f.ny=a.ssny
    )

select t.*,m.ny as ssny,m.swjgmc,m.sbr,m.sbtime from tjbb_task_sub t,tjbb_task m where
m.bbdldm=t.bbdldm and m.swjgdm=t.swjgdm and t.ny=m.ny and
t.bbdm=#{bbdm}

    and m.swjgdm=#{swjgdm}


    and (m.sjswjg=#{swjgdm} or m.swjgdm=#{swjgdm})

 and m.status='20' and exists
  (select 1 from tjbb_task k where k.swjgdm=#{swjgdm}
      /**and k.status='20'**/
      and k.bbdldm=t.bbdldm
      and k.ny=t.ny and exists
     (select 1 from tjbb_task where status='20' group by bbdldm having max(ny)=k.ny)
  )
order by t.swjgdm

select t.*,m.ny as ssny,m.swjgmc,m.sbr,m.sbtime from tjbb_task_sub t,tjbb_task m where
m.bbdldm=t.bbdldm and m.swjgdm=t.swjgdm and t.ny=m.ny and
t.bbdm=#{bbdm}

    and m.swjgdm=#{swjgdm}


    and (m.sjswjg=#{swjgdm} or m.swjgdm=#{swjgdm})

and m.status='20' and exists
(select 1 from tjbb_task k where k.swjgdm=#{swjgdm}
/**and k.status='20'**/
and k.bbdldm=t.bbdldm
and k.ny=t.ny ) and t.ny=#{ssny}
order by t.swjgdm

mapper.update:
update ${fname}
    set

      ${item.col}=#{item.coldata}

where ssny=#{ssny} and swjgdm=#{swjgdm} and bblc=#{bblc}

create table ${tablename}
(
SSNY        VARCHAR2(6) not null,
BBLC        VARCHAR2(10) not null,
SWJGDM      VARCHAR2(32) not null
)

mapper.insert:
begin

    insert into ${fname}(ssny,bblc,swjgdm)
    values   (
    #{item.ssny},#{item.bblc},
    #{item.swjgdm});

COMMIT;
end;

begin
insert into tjbb_task_sub (bbid,bbdm,swjgdm,ny,hztime,hzr,bbdldm) values ( #{item.bbid}, #{item.bbdm}, #{item.swjgdm}, #{item.ny}, #{item.hztime}, #{item.hzr}, #{item.bbdldm});
COMMIT; end;

begin
insert into ${tablename}(swjgdm,bblc,ssny,
${fname},
${item},${item}_HZ
) select #{swjgdm},#{item.tblc},#{ssny},
#{fvalue},
decode(nvl(b.${item},0),0,0.99,ROUND((a.${item}-b.${item})/b.${item},4)), decode(nvl(b.${item}_HZ,0),0,0.99,ROUND((a.${item}_HZ-b.${item}_HZ)/b.${item}_HZ,4))
from ${tablename} a left join ${tablename} b on a.swjgdm=b.swjgdm and a.bblc=b.bblc and b.ssny=to_char(ADD_MONTHS(to_date(#{ssny},'YYYYMM'),-12),'YYYYMM') where a.swjgdm=#{swjgdm} and a.bblc=#{item.bblc} and a.ssny=#{ssny};
COMMIT; end;

begin
update ${tablename} t set ${item.tblc} = (select decode(b.${item.bblc},0,99.99,null,b.${item.bblc}, round((a.${item.bblc} - b.${item.bblc})*100 / b.${item.bblc}, 2)) from ${tablename} a left join ${tablename} b on (a.swjgdm = b.swjgdm and a.bblc = b.bblc and b.ssny =to_char(ADD_MONTHS(to_date(#{ssny},'YYYYMM'),-12),'YYYYMM')) where a.ssny = #{ssny} and a.swjgdm = #{swjgdm} and t.bblc=a.bblc) where t.ssny = #{ssny} and t.swjgdm = #{swjgdm};
update ${tablename} t set ${item.tblc}_HZ = (select decode(b.${item.bblc}_HZ,0,99.99,null,b.${item.bblc}_HZ, round((a.${item.bblc}_HZ - b.${item.bblc}_HZ)*100 / b.${item.bblc}_HZ, 2)) from ${tablename} a left join ${tablename} b on (a.swjgdm = b.swjgdm and a.bblc = b.bblc and b.ssny =to_char(ADD_MONTHS(to_date(#{ssny},'YYYYMM'),-12),'YYYYMM')) where a.ssny = #{ssny} and a.swjgdm = #{swjgdm} and t.bblc=a.bblc) where t.ssny = #{ssny} and t.swjgdm = #{swjgdm};
COMMIT; end;

begin

    update ${tablename} a
    set
    ${item.zbcol} =
    decode(
    (select ${item.bblc} from  ${tablename} where ssny = #{ssny} and swjgdm = #{swjgdm} and bblc = '01')
    ,0,99.99,
    round(a.${item.bblc}*100/(select ${item.bblc} from  ${tablename} where ssny = #{ssny} and swjgdm = #{swjgdm} and bblc = '01'),2)
    )
    where a.ssny = #{ssny}
    and a.swjgdm = #{swjgdm};

    update ${tablename} a
    set
    ${item.zbcol}_HZ =
    decode(
    (select ${item.bblc}_HZ from  ${tablename} where ssny = #{ssny} and swjgdm = #{swjgdm} and bblc = '01')
    ,0,99.99,
    round(a.${item.bblc}_HZ*100/(select ${item.bblc}_HZ from  ${tablename} where ssny = #{ssny} and swjgdm = #{swjgdm} and bblc = '01'),2)
    )
    where a.ssny = #{ssny}
    and a.swjgdm = #{swjgdm};

COMMIT;
end;

begin

    update ${tablename} a
    set
    ${item.zbcol} =decode(${item.fmCol},0,'99.99',${item.formula})
    where a.ssny = #{ssny}
    and a.swjgdm = #{swjgdm}
    and not exists
    (select 1 from tjbb_line_item e where e.bbdm=#{bbdm} and e.bblc=a.bblc
         and e.allowformula='N' and qybj='Y')
    ;
    update ${tablename} a
    set
    ${item.zbcol}_HZ =decode(${item.fmCol}_HZ,0,'99.99',${item.formulaHz})
    where a.ssny = #{ssny}
    and a.swjgdm = #{swjgdm}
    and not exists
    (select 1 from tjbb_line_item e where e.bbdm=#{bbdm} and e.bblc=a.bblc
    and e.allowformula='N' and qybj='Y')
    ;

COMMIT;
end;

